"""Conservative telemetry erasure of frozen P6/P8, generated by derive_off.py.

Policy, data structures and branch order are retained. No counters, event log,
internal timers, peak statistics or P7/P8 reporting. Source-size UTF8 in fresh
is dead and erased; selective raw UTF8 is retained as a shared key/L operand.
Rendering and its original UTF8 encoding remain. Supported research entry:
run_fresh(public) with default text_scoped; run_selective(public, cache).
"""
from collections import Counter
from collections.abc import Mapping
from functools import cmp_to_key
from types import MappingProxyType
import hashlib
import json
from bindings import P6, SEMANTIC_FINGERPRINT
BASE = P6.BASE
METHODS = P6.METHODS
scope_from_text = P6.scope_from_text
scoped_top = P6.scoped_top
writes = P6.writes
preimage = P6.preimage
execute = P6.execute
render = P6.render
frozen = P6.frozen
STAGES = ('cheap', 'contract', 'detail')
MAX_ENTRIES, MAX_BYTES = (64, 65536)
MIN_CHARS, HIT_CAP = (256, 255)
META_BYTES = 80
ACTION_WEIGHT = 8
WARM_ACTIONS = 8

def plain(value):
    if isinstance(value, Mapping):
        return {k: plain(v) for k, v in value.items()}
    if isinstance(value, (tuple, list)):
        return [plain(v) for v in value]
    if isinstance(value, (set, frozenset)):
        return [plain(v) for v in sorted(value, key=repr)]
    return value

def encode(value):
    return json.dumps(plain(value), ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')

def immutable(value):
    if isinstance(value, Mapping):
        return MappingProxyType({k: immutable(v) for k, v in value.items()})
    if isinstance(value, (tuple, list)):
        return tuple((immutable(v) for v in value))
    if isinstance(value, (set, frozenset)):
        return frozenset((immutable(v) for v in value))
    return value

class SelectiveCache:
    """Greedy admission by observed warm surplus and bounded past hits.

    Victim ranking and benefit comparisons are heuristic, not predictions of
    the actual future or a solution of the capacity-constrained offline optimum.
    """

    def __init__(self, *, directory=True, max_entries=MAX_ENTRIES, max_bytes=MAX_BYTES):
        if min(max_entries, max_bytes) < 0:
            raise ValueError('negative capacity')
        self.directory = directory
        self.max_entries, self.max_bytes = (max_entries, max_bytes)
        self.entries = {}
        self.lengths = Counter()
        self.retained_bytes = 0
        self.next_order = 0

    def possible(self, characters):
        if self.directory:
            possible = self.lengths.get(characters, 0) > 0
        else:
            possible = bool(self.entries)
        if not possible:
            pass
        return possible

    def get(self, key):
        item = self.entries.get(key)
        if item is None:
            return None
        item['hits'] = min(HIT_CAP, item['hits'] + 1)
        return item['stages']

    def admit(self, key_factory, context, raw_size, characters, values):
        """Caller checked full global three-stage eligibility after real parsing."""
        stages = {}
        for name in STAGES:
            value = values[name]
            length = len(encode(value))
            stages[name] = (immutable(value), length)
        payload = sum((size for _, size in stages.values()))
        surplus = raw_size - len(context) - payload - ACTION_WEIGHT * WARM_ACTIONS
        size = len(context) + raw_size + payload + META_BYTES
        if surplus <= 0:
            return
        if not self.max_entries or size > self.max_bytes:
            return
        victims = []
        if len(self.entries) + 1 > self.max_entries or self.retained_bytes + size > self.max_bytes:
            ranked = []
            for key, item in self.entries.items():
                weight = (item['hits'] + 1) * item['surplus']
                ranked.append((key, item, weight))

            def order(left, right):
                a, b = (left[2] * right[1]['size'], right[2] * left[1]['size'])
                if a != b:
                    return -1 if a < b else 1
                return (left[1]['order'] > right[1]['order']) - (left[1]['order'] < right[1]['order'])
            ranked.sort(key=cmp_to_key(order))
            freed, lost = (0, 0)
            for key, item, weight in ranked:
                victims.append(key)
                freed += item['size']
                lost += weight
                if len(self.entries) - len(victims) + 1 <= self.max_entries and self.retained_bytes - freed + size <= self.max_bytes:
                    break
            if surplus <= lost:
                return
        for victim in victims:
            item = self.entries.pop(victim)
            self.retained_bytes -= item['size']
            self.lengths[item['characters']] -= 1
            if not self.lengths[item['characters']]:
                del self.lengths[item['characters']]
        key = key_factory()
        self.entries[key] = {'stages': MappingProxyType(stages), 'size': size, 'characters': characters, 'surplus': surplus, 'hits': 0, 'order': self.next_order}
        self.next_order += 1
        self.lengths[characters] += 1
        self.retained_bytes += size

def digest(records):
    serialized = json.dumps(records, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')
    return hashlib.sha256(serialized).hexdigest()

def validate(public):
    records, expected = (public['records'], public['snapshot'])
    if [r['seq'] for r in records] != list(range(expected['head'] + 1)):
        return 'record_gap_or_order'
    if digest(records) != expected['digest']:
        return 'snapshot_mismatch'
    return None

def run_fresh(public, method='text_scoped', *, oracle_scopes=None):
    if method not in METHODS:
        raise ValueError(method)
    if method != 'oracle_scoped' and oracle_scopes is not None:
        raise ValueError('Oracle annotations are forbidden for text-only methods')
    if method == 'oracle_scoped' and oracle_scopes is None:
        raise ValueError('Oracle method requires explicit gold may-write annotations')
    if method == 'frozen_lazy':
        return frozen(public)
    records, entities = (public['records'], public['entities'])
    error = validate(public)
    if error:
        return {'status': 'integrity_failure', 'reason': error, 'prediction': {}, 'selected': [], 'output_bytes': 0, 'scope_trace': []}
    requested = BASE.parse_query(public['query'], entities)
    if method == 'full_history' or requested is None:
        status = 'full_history' if method == 'full_history' else 'unsupported_query'
        selected = list(range(len(records)))
        return {'status': status, 'prediction': {}, 'selected': selected, 'output_bytes': len(render(public, selected, status).encode('utf-8')), 'scope_trace': []}
    universe = BASE.facts(entities)
    cache, trace = ({}, [])

    def read(index, demand):
        if index in cache:
            return cache[index]
        text = records[index]['text']
        ev = BASE.parse(text, entities)
        if ev['kind'] == 'havoc':
            if method == 'oracle_scoped':
                w = frozenset((tuple(x) for x in oracle_scopes[index]))
                if not w <= set(universe):
                    raise ValueError('Oracle scope outside public universe')
                rule = 'oracle'
            else:
                known, rule = scope_from_text(text, entities)
                w = frozenset(universe) if known is None else known
                if method == 'global_control':
                    w = frozenset(universe)
            relevant = bool(set(demand) & w)
            trace.append({'index': index, 'rule': rule, 'may_write': [list(f) for f in sorted(w)], 'proper_scope': len(w) < len(universe), 'detail_avoided': not relevant})
            if relevant:
                ev = BASE.parse(text, entities, deep=True)
            if ev['kind'] == 'havoc':
                ev = scoped_top(w)
        cache[index] = ev
        return ev
    if method == 'text_scoped_eager':
        for index in range(len(records)):
            read(index, universe)
    demand, selected = (set(requested), [])
    for index in range(len(records) - 1, -1, -1):
        if not demand:
            break
        ev = read(index, demand)
        if demand & writes(ev, universe):
            selected.append(index)
            demand = preimage(ev, demand, universe)
    selected.sort()
    abstract = execute((cache[index] for index in selected), universe)
    unresolved = any((cache[index]['kind'] in ('havoc', 'scoped_top') for index in selected))
    certified = all((abstract[f] is not None and len(abstract[f]) == 1 for f in requested))
    status = 'certified_model' if certified else 'opaque_fallback' if unresolved or demand else 'ambiguous'
    if status == 'opaque_fallback':
        selected = list(range(len(records)))
    prediction = {f'{f[0]}.{f[1]}': None if abstract[f] is None else sorted(abstract[f], key=repr) for f in sorted(requested)}
    return {'status': status, 'prediction': prediction, 'selected': selected, 'output_bytes': len(render(public, selected, status).encode('utf-8')), 'remaining_input_facts': sorted(demand), 'scope_trace': trace}

def run_selective(public, cache, *, namespace='v1'):
    records, entities = (public['records'], public['entities'])
    error = validate(public)
    if error:
        return {'status': 'integrity_failure', 'reason': error, 'prediction': {}, 'selected': [], 'output_bytes': 0, 'scope_trace': []}
    requested = P6.BASE.parse_query(public['query'], entities)
    if requested is None:
        selected, status = (list(range(len(records))), 'unsupported_query')
        return {'status': status, 'prediction': {}, 'selected': selected, 'output_bytes': len(P6.render(public, selected, status).encode()), 'scope_trace': []}
    context = None

    def get_context():
        nonlocal context
        if context is None:
            context = encode((SEMANTIC_FINGERPRINT, namespace, tuple(entities)))
        return context
    universe = P6.BASE.facts(entities)
    query_events, trace = ({}, [])

    def read(index, demand):
        if index in query_events:
            return query_events[index]
        text = records[index]['text']
        raw = text.encode('utf-8')
        size = len(raw)
        characters = len(text)
        eligible = characters >= MIN_CHARS
        key, ctx, cached_stages = (None, None, None)

        def get_key():
            nonlocal key
            if key is None:
                key = (ctx, raw)
            return key
        if not eligible:
            pass
        elif cache.possible(characters):
            ctx = get_context()
            cached_stages = cache.get(get_key())
        values = {}

        def stage(name):
            if cached_stages is not None:
                value, length = cached_stages[name]
                return value
            value = P6.scope_from_text(text, entities) if name == 'contract' else P6.BASE.parse(text, entities, deep=name == 'detail')
            if eligible:
                values[name] = value
            return value
        ev = stage('cheap')
        if ev['kind'] == 'havoc':
            known, rule = stage('contract')
            w = frozenset(universe) if known is None else known
            relevant = bool(set(demand) & w)
            trace.append({'index': index, 'rule': rule, 'may_write': [list(f) for f in sorted(w)], 'proper_scope': len(w) < len(universe), 'detail_avoided': not relevant})
            if relevant:
                ev = stage('detail')
            if ev['kind'] == 'havoc':
                ev = P6.scoped_top(w)
        if eligible and cached_stages is None:
            if set(values) == set(STAGES) and values['cheap']['kind'] == 'havoc' and (values['contract'][0] is None):
                if ctx is None:
                    ctx = get_context()
                cache.admit(get_key, ctx, size, characters, values)
        query_events[index] = ev
        return ev
    demand, selected = (set(requested), [])
    for index in range(len(records) - 1, -1, -1):
        if not demand:
            break
        ev = read(index, demand)
        if demand & P6.writes(ev, universe):
            selected.append(index)
            demand = P6.preimage(ev, demand, universe)
    selected.sort()
    abstract = P6.execute((query_events[i] for i in selected), universe)
    unresolved = any((query_events[i]['kind'] in ('havoc', 'scoped_top') for i in selected))
    certified = all((abstract[f] is not None and len(abstract[f]) == 1 for f in requested))
    status = 'certified_model' if certified else 'opaque_fallback' if unresolved or demand else 'ambiguous'
    if status == 'opaque_fallback':
        selected = list(range(len(records)))
    prediction = {f'{f[0]}.{f[1]}': None if abstract[f] is None else sorted(abstract[f], key=repr) for f in sorted(requested)}
    return {'status': status, 'prediction': prediction, 'selected': selected, 'output_bytes': len(P6.render(public, selected, status).encode()), 'remaining_input_facts': sorted(demand), 'scope_trace': trace}
